import { useEffect, useMemo, useState } from "react";
import {
  Form,
  Button,
  Row,
  Col,
  Container,
  Alert,
  Card,
} from "react-bootstrap";
import { getAccount } from "../api/api";
import { useNavigate } from "react-router-dom";
import useLocalStorage from "./useLocalStorage";

function Login() {
  const navigate = useNavigate();
  const [accounts, setAccounts] = useState([]);
  const [email, setEmail] = useState([]);
  const [password, setPassword] = useState([]);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");

  const loadCourses = () => {
    getAccount()
      .then((data) => setAccounts(data))
      .catch(() => setError("Không thể tải danh sách khóa học."));
  };

  useEffect(() => {
    loadCourses();
  }, []);

  const filteredAccount = useMemo(() => {
    const keyword = search.trim();

    return accounts.filter((a) => {
      const matchesEmail = !keyword || a.email.startsWith(keyword);
      const matchesPassword = !keyword || a.password.startsWith(keyword);

      return matchesEmail && matchesPassword;
    });
  }, [accounts, search, email, password]);

  return (
    <Container className="py-4">
      <Col>
        <h3>Login</h3>
        <Row md={9}>
          <Form.Control
            placeholder="email of student or lecture"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </Row>
        <Row md={9}>
          <Form.Control
            placeholder="Enter password"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </Row>
        <Button
          onClick={() => navigate(`/syllabus`)}
          variant="primary"
        >
          →
        </Button>
      </Col>
    </Container>
  );
}

export default Login;
